Properties props = new Properties();
props.put("bootstrap.servers", "localhost:9092");
props.put("key.serializor", "StringSerializer");
props.put("value.serializer", "StringSerializer");

StreamsBuilder builder = new StreamsBuilder();
builder.stream("orders")
  .filter((key, value) -> value.contains("COMPLETED"))
  .to("completed-orders");

Properties props = new Properties();
props.put("transactional.id", "order-processor");
KafkaProducer<String, String> producer =
    new KafkaProducer<>(props);
producer.initTransactions();
producer.beginTransaction();
producer.send(new ProducerRecord<>("orders", "key1", "val1"));
producer.send(new ProducerRecord<>("payments", "key1", "val2"));
producer.commitTransaction();

consumer.subscribe(List.of("events"),
  new ConsumerRebalanceListener() {
    public void onPartitionsRevoked(
        Collection<TopicPartition> parts) {
      consumer.commitSync();
    }
    public void onPartitionsAssigned(
        Collection<TopicPartition> parts) {
      // no-op
    }
  });

KStream<String, String> stream = builder.stream("clicks");
KTable<String, Long> counts = stream
  .groupByKey()
  .count(Materialized.as("click-counts"));
counts.toStream().to("click-analytics");
